<?php
require_once __DIR__.'/../includes/auth.php'; require_role('admin');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);if($id){$s=$pdo->prepare("DELETE FROM equipment WHERE id=?");$s->execute([$id]);flash('Equipment deleted.');}else{$s=$pdo->prepare("INSERT INTO equipment(equipment_code,name,category_id,description,quantity,available_quantity,laboratory_id,condition_status) VALUES(?,?,?,?,?,?,?,?)");$s->execute([trim($_POST['code']),trim($_POST['name']),$_POST['category_id']?:null,trim($_POST['description']),$_POST['quantity'],$_POST['quantity'],$_POST['laboratory_id'],$_POST['condition_status']]);flash('Equipment added.');}redirect('equipment.php');}
$items=$pdo->query("SELECT e.*,l.name lab FROM equipment e LEFT JOIN laboratories l ON l.id=e.laboratory_id ORDER BY e.id DESC")->fetchAll();$labs=$pdo->query("SELECT id,name FROM laboratories")->fetchAll();$cats=$pdo->query("SELECT id,name FROM equipment_categories")->fetchAll();
page_header('Equipment Management','admin');?>
<div class="panel mb-4"><h2 class="section-title">Add equipment</h2><form method="post" class="row g-3"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="col-md-2"><input class="form-control" name="code" placeholder="Equipment ID" required></div><div class="col-md-3"><input class="form-control" name="name" placeholder="Equipment name" required></div><div class="col-md-2"><select class="form-select" name="category_id"><option value="">Category</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach?></select></div><div class="col-md-2"><select class="form-select" name="laboratory_id" required><option value="">Laboratory</option><?php foreach($labs as $l):?><option value="<?=$l['id']?>"><?=e($l['name'])?></option><?php endforeach?></select></div><div class="col-md-1"><input class="form-control" type="number" min="1" name="quantity" placeholder="Qty" required></div><div class="col-md-2"><select class="form-select" name="condition_status"><option>Good</option><option>Under Maintenance</option></select></div><div class="col-12"><input class="form-control" name="description" placeholder="Description"></div><div class="col-12"><button class="btn btn-primary">Add equipment</button></div></form></div>
<div class="panel"><h2 class="section-title">Equipment inventory</h2><div class="table-responsive"><table class="table"><thead><tr><th>ID</th><th>Name</th><th>Laboratory</th><th>Quantity</th><th>Available</th><th>Condition</th><th>Action</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><?=e($i['equipment_code'])?></td><td><?=e($i['name'])?></td><td><?=e($i['lab'])?></td><td><?=$i['quantity']?></td><td><?=$i['available_quantity']?></td><td><?=status_badge($i['condition_status'])?></td><td><form method="post" onsubmit="return confirm('Delete this equipment?')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$i['id']?>"><button class="btn btn-sm btn-outline-light">Delete</button></form></td></tr><?php endforeach?></tbody></table></div></div><?php page_footer();?>
